CREATE TABLE `admins` (`user_id` text PRIMARY KEY NOT NULL, `email` text NOT NULL, `display_name` text NOT NULL, `created_at` text NOT NULL);
CREATE TABLE `content` (`id` text PRIMARY KEY NOT NULL, `slug` text NOT NULL UNIQUE, `title` text NOT NULL, `subtitle` text, `summary` text NOT NULL, `body` text NOT NULL, `type` text NOT NULL, `topic` text NOT NULL, `author` text NOT NULL, `tags` text DEFAULT '[]' NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `featured` integer DEFAULT false NOT NULL, `external_kind` text, `source_name` text, `source_url` text, `permission_note` text, `abstract` text, `references` text DEFAULT '[]' NOT NULL, `doi` text, `attachment_key` text, `published_at` text, `updated_at` text NOT NULL, `created_at` text NOT NULL);
CREATE TABLE `services` (`id` text PRIMARY KEY NOT NULL, `title` text NOT NULL, `description` text NOT NULL, `audience` text NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `sort_order` integer DEFAULT 0 NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE `learning_paths` (`id` text PRIMARY KEY NOT NULL, `slug` text NOT NULL UNIQUE, `title` text NOT NULL, `description` text NOT NULL, `topic` text NOT NULL, `difficulty` text NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE `lessons` (`id` text PRIMARY KEY NOT NULL, `path_id` text NOT NULL, `slug` text NOT NULL UNIQUE, `title` text NOT NULL, `summary` text NOT NULL, `body` text NOT NULL, `video_url` text, `resource_key` text, `sort_order` integer DEFAULT 0 NOT NULL, `status` text DEFAULT 'draft' NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE `contacts` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `email` text NOT NULL, `subject` text NOT NULL, `enquiry_type` text NOT NULL, `message` text NOT NULL, `status` text DEFAULT 'new' NOT NULL, `ip_hash` text NOT NULL, `created_at` text NOT NULL);
CREATE INDEX `contacts_ip_created_idx` ON `contacts` (`ip_hash`, `created_at`);
CREATE TABLE `subscribers` (`id` text PRIMARY KEY NOT NULL, `email` text NOT NULL UNIQUE, `name` text, `status` text DEFAULT 'pending' NOT NULL, `provider_id` text, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE `site_settings` (`key` text PRIMARY KEY NOT NULL, `value` text NOT NULL, `updated_at` text NOT NULL);
